function parsePolicyExceptions(markdown) {
  const start = markdown.indexOf("## Policy Exceptions");
  const end = markdown.indexOf("## Correction Notices");
  const slice =
    start >= 0 && end > start ? markdown.slice(start, end) : "";
  const ids = new Set();
